mapper.select:
select * from dh_dataset_column
where dataset_id = #{datasetId} and schema_id = #{schemaId}
order by ordinal_position

mapper.update:
update dh_dataset
set active_job_id = #{jobId}, lock_version = lock_version + 1, update_time = sysdate(3)
where dataset_id = #{datasetId} and del_flag = '0' and status = 'ACTIVE'
  and active_job_id is null and current_version_id = #{sourceVersionId}
  and lock_version = #{sourceLockVersion}

update dh_dataset
set active_job_id = null, lock_version = lock_version + 1, update_time = sysdate(3)
where dataset_id = #{datasetId} and active_job_id = #{jobId}

update dh_dataset_version
set status = 'ARCHIVED', retention_until = #{retentionUntil}
where version_id = #{versionId} and status = 'ACTIVE'
